'use strict';
let exportJobs=[],exportQueueRunning=false,stopQueueAfterCurrent=false,exportQueueFolder='',queueWorkspace=null;
const rendererForQueue=$('renderVideo').onclick;
document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openExportQueue">Export queue</button>');$('renderVideo').before(Object.assign(document.createElement('button'),{id:'queueCurrentExport',textContent:'Add to queue'}));
document.body.insertAdjacentHTML('beforeend',`<dialog id="exportQueueDialog"><div class="tool-heading"><div><div class="eyebrow">RENDER YOUR NEXT STORIES</div><h2>Export queue</h2></div><button id="closeExportQueue">Close</button></div><p class="note">Each job keeps a snapshot of its project. You can queue different formats or projects. Desktop exports render every timeline frame. Browser exports run in real time; keep the browser visible.</p><div class="pro-tool-row"><button id="addCurrentQueue">＋ Current project</button><label class="button">Add project files<input id="queueProjectFiles" type="file" accept="application/json,.json" multiple hidden></label><button id="chooseQueueFolder">Choose output folder</button><button id="clearFinishedExports">Clear finished</button></div><p id="exportQueueFolder" class="note">Browser exports use your Downloads folder.</p><div id="exportQueueJobs" class="export-queue-jobs"></div><p id="exportQueueProgress" class="analysis-summary">Ready.</p><div class="pro-tool-row"><button id="startExportQueue" class="primary">Start queue</button><button id="stopExportQueue" disabled>Stop after current</button></div></dialog>`);
function queueFileName(job){const base=(job.name||job.project.title||'Animation').replace(/[\\/:*?"<>|]/g,'-').replace(/[. ]+$/,'').slice(0,100)||'Animation';return base+'.'+job.format}
async function persistExportQueue(){await workspacePut('exportQueue',exportJobs)}
function createExportJob(p,settings={}){return{id:uid(),name:p.title||'Animation',project:structuredClone(p),resolution:String(settings.resolution||$('resolution').value||1920),format:settings.format||$('videoFormat').value||'webm',canvasFormat:settings.canvasFormat||p.canvasFormat||'landscape',range:settings.range||(p===project&&typeof readExportRange==='function'?readExportRange():{start:0,end:p.scenes.reduce((n,s)=>n+s.duration,0)}),status:'queued',created:Date.now(),error:'',output:''}}
async function addQueueProject(p,settings){await exportQueueReady;if(exportJobs.length>=10)return toast('Keep up to 10 export jobs. Clear finished jobs to add more.');if(!valid(p))return toast('This project cannot be queued. Check its content first.');const job=createExportJob(p,settings);try{await workspacePut('exportQueue',[...exportJobs,job]);exportJobs.push(job);renderExportQueue();toast('Project snapshot added to the export queue.')}catch{toast('Could not store this job. Free some device storage or export this project directly.')}}
function showExportQueue(){renderExportQueue();$('exportQueueFolder').textContent=window.studioDesktop?(exportQueueFolder||'Choose an output folder once for this queue run.'):'Browser exports use your Downloads folder.';if(!$('exportQueueDialog').open)$('exportQueueDialog').showModal()}
function renderExportQueue(){const list=$('exportQueueJobs');list.replaceChildren();if(!exportJobs.length)list.innerHTML='<p class="note">Add the current project or import saved project files to get started.</p>';for(const job of exportJobs){const card=document.createElement('article');card.className='export-job '+job.status;const name=document.createElement('input');name.value=job.name;name.maxLength=100;name.setAttribute('aria-label','Export filename');name.disabled=exportQueueRunning;name.onchange=()=>{job.name=name.value.trim()||job.project.title;persistExportQueue().catch(()=>toast('Could not save queue changes.'))};const state=document.createElement('strong');state.textContent=job.status;const settings=document.createElement('div');settings.className='pro-tool-row';for(const[key,options]of[['canvasFormat',[['landscape','16:9'],['portrait','9:16 vertical'],['square','1:1 square']]],['resolution',[['960','Draft'],['1920','HD'],['3840','High resolution']]],['format',[['mp4','MP4'],['webm','WebM'],['mov','MOV'],['gif','GIF · silent']]]]){const select=document.createElement('select');select.dataset.setting=key;select.setAttribute('aria-label','Job '+key);for(const[value,text]of options){const option=document.createElement('option');option.value=value;option.textContent=text;if(key==='format'&&value!=='webm'&&!window.studioDesktop)option.disabled=true;select.append(option)}select.value=job[key];select.disabled=exportQueueRunning;select.onchange=()=>{job[key]=select.value;if(job.status==='done'||job.status==='error'){job.status='queued';job.output='';job.error=''}persistExportQueue().catch(()=>toast('Could not save queue changes.'));renderExportQueue()};settings.append(select)}const info=document.createElement('p'),dimensions=exportGeometry(job.resolution,{canvasFormat:job.canvasFormat});info.className='note';info.textContent=dimensions.width+' × '+dimensions.height+' · '+(job.range?job.range.end-job.range.start:job.project.scenes.reduce((n,s)=>n+s.duration,0)).toFixed(1)+'s'+(job.range?' · range '+job.range.start.toFixed(2)+'–'+job.range.end.toFixed(2)+'s':'')+(job.output?' · '+job.output:'')+(job.error?' · '+job.error:'');const remove=document.createElement('button');remove.textContent=job.status==='error'?'Retry':'Remove';remove.disabled=exportQueueRunning;remove.onclick=()=>{if(job.status==='error'){job.status='queued';job.error=''}else exportJobs=exportJobs.filter(j=>j.id!==job.id);persistExportQueue().catch(()=>toast('Could not save queue changes.'));renderExportQueue()};card.append(name,state,settings,info,remove);list.append(card)}for(const id of ['startExportQueue','addCurrentQueue','chooseQueueFolder','clearFinishedExports','queueProjectFiles','closeExportQueue'])$(id).disabled=exportQueueRunning;$('startExportQueue').disabled||=!exportJobs.some(j=>j.status==='queued');$('stopExportQueue').disabled=!exportQueueRunning}
$('queueCurrentExport').onclick=async()=>{await addQueueProject(project);$('exportDialog').close();showExportQueue()};$('openExportQueue').onclick=()=>{stop();showExportQueue()};$('closeExportQueue').onclick=()=>{if(!exportQueueRunning)$('exportQueueDialog').close()};$('exportQueueDialog').addEventListener('cancel',e=>{if(exportQueueRunning)e.preventDefault()});$('addCurrentQueue').onclick=()=>addQueueProject(project);$('clearFinishedExports').onclick=()=>{exportJobs=exportJobs.filter(j=>j.status!=='done');persistExportQueue().catch(()=>toast('Could not save queue changes.'));renderExportQueue()};
$('chooseQueueFolder').onclick=async()=>{if(!window.studioDesktop?.chooseExportFolder)return toast('Folder selection is available in the updated desktop app. Browser exports use Downloads.');const result=await window.studioDesktop.chooseExportFolder();if(!result.canceled){exportQueueFolder=result.path;$('exportQueueFolder').textContent=result.path}};
$('queueProjectFiles').onchange=async e=>{const files=Array.from(e.target.files);e.target.value='';for(const file of files){try{if(file.size>300e6)throw Error('Choose a project smaller than 300 MB.');const p=JSON.parse(await file.text());if(!valid(p))throw Error('This project file is invalid.');await addQueueProject(p)}catch(error){toast(file.name+': '+error.message)}}};
const storeBeforeQueue=storeWorkspace;storeWorkspace=function(snapshot){return storeBeforeQueue(queueWorkspace&&snapshot===project?queueWorkspace.project:snapshot)};
const toastBeforeQueue=toast;toast=function(message){toastBeforeQueue(message);if(exportQueueRunning&&/^Rendering /.test(message))$('exportQueueProgress').textContent=message};
async function captureQueueJob(job){
 const original={project,sceneIndex,time,selected,selectedAudio,audio:[...audioBuffers],resolution:$('resolution').value,format:$('videoFormat').value,scope:$('exportScope')?.value,rangeStart:$('exportRangeStart')?.value,rangeEnd:$('exportRangeEnd')?.value,images:new Set(images.keys())},savedDownload=download;
 queueWorkspace=original;let blob=null;
 try{project=structuredClone(job.project);project.canvasFormat=job.canvasFormat;sceneIndex=0;time=0;selected=null;selectedAudio=null;$('resolution').value=job.resolution;$('videoFormat').value='webm';await hydrateAudio();if($('exportScope')&&job.range){$('exportScope').value='range';$('exportRangeStart').value=job.range.start;$('exportRangeEnd').value=job.range.end}if(window.studioDesktop?.beginFrameExport){const result=await renderNativeFrames({folder:exportQueueFolder,name:job.name,format:job.format,range:job.range});return{nativePath:result.path}}download=async value=>{blob=value};await rendererForQueue();if(!blob)throw Error($('toast').textContent||'No video was produced.');return blob}
 finally{download=savedDownload;project=original.project;sceneIndex=original.sceneIndex;time=original.time;selected=original.selected;selectedAudio=original.selectedAudio;audioBuffers.clear();for(const[id,buffer]of original.audio)audioBuffers.set(id,buffer);$('resolution').value=original.resolution;$('videoFormat').value=original.format;if($('exportScope')){$('exportScope').value=original.scope;$('exportRangeStart').value=original.rangeStart;$('exportRangeEnd').value=original.rangeEnd}for(const src of images.keys())if(!original.images.has(src))images.delete(src);queueWorkspace=null;render();layoutProjectFormat()}
}
async function startExportQueue(){await exportQueueReady;if(exportQueueRunning||recording||audioBusy||videoImportBusy)return;if(!exportJobs.some(j=>j.status==='queued'))return;if(window.studioDesktop?.saveQueuedExport&&!exportQueueFolder){const result=await window.studioDesktop.chooseExportFolder();if(result.canceled)return;exportQueueFolder=result.path;$('exportQueueFolder').textContent=result.path}stop();exportQueueRunning=true;stopQueueAfterCurrent=false;window.editorTaskBusy=true;const main=document.querySelector('main'),header=document.querySelector('header'),oldInert=[main.inert,header.inert];main.inert=header.inert=true;renderExportQueue();try{for(const job of exportJobs){if(job.status!=='queued')continue;if(stopQueueAfterCurrent)break;job.status='running';job.error='';await persistExportQueue();renderExportQueue();$('exportQueueProgress').textContent='Rendering '+job.name+'…';try{const blob=await captureQueueJob(job),name=queueFileName(job);if(blob.nativePath){job.output=blob.nativePath}else if(window.studioDesktop?.saveQueuedExport){const result=await window.studioDesktop.saveQueuedExport(await blob.arrayBuffer(),{folder:exportQueueFolder,name,mp4:job.format==='mp4'});job.output=result.path}else if(window.studioDesktop&&job.format==='mp4'){const result=await window.studioDesktop.exportMp4(await blob.arrayBuffer());if(result.canceled)throw Error('Saving was canceled.');job.output=result.path}else{if(job.format==='mp4')throw Error('Batch MP4 encoding is available in the desktop app. Choose WebM in this browser.');await download(blob,name);job.output=name}job.status='done'}catch(error){job.status='error';job.error=String(error.message||error).slice(0,500);stopQueueAfterCurrent=true}await persistExportQueue();renderExportQueue()}$('exportQueueProgress').textContent=stopQueueAfterCurrent?'Queue stopped. Remaining jobs are ready to continue.':'Queue complete.'}catch(error){$('exportQueueProgress').textContent=error.message||'Could not update the queue.'}finally{exportQueueRunning=false;window.editorTaskBusy=false;main.inert=oldInert[0];header.inert=oldInert[1];renderExportQueue();render()}}
$('startExportQueue').onclick=startExportQueue;$('stopExportQueue').onclick=()=>{stopQueueAfterCurrent=true;$('exportQueueProgress').textContent='Stopping after the current job is saved…'};
const exportQueueReady=workspaceValue('exportQueue').then(list=>{exportJobs=Array.isArray(list)?list.filter(j=>j&&valid(j.project)&&['960','1920','3840'].includes(j.resolution)&&['webm','mp4','mov','gif'].includes(j.format)&&Object.hasOwn(projectFormats,j.canvasFormat)&&(!j.range||Number.isFinite(j.range.start)&&Number.isFinite(j.range.end)&&j.range.start>=0&&j.range.end>j.range.start&&j.range.end<=j.project.scenes.reduce((n,s)=>n+s.duration,0)+.001)).slice(0,10):[];for(const job of exportJobs)if(job.status==='running'){job.status='queued';job.error='Interrupted export; ready to retry.'}renderExportQueue()}).catch(()=>{});
